INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Neuron Anatomy & Physiology','easy','flashcard','What is the resting membrane potential of a typical neuron?','["-70 mV, maintained by Na+/K+ ATPase and K+ leak channels. Inside is negative relative to outside."]','A','Think: seventy negative — the RESTING neuron is at -70.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Neuron Anatomy & Physiology','easy','flashcard','What is the threshold potential for action potential generation in most neurons?','["Approximately -55 mV (about 15 mV above resting potential of -70 mV). At threshold, enough voltage-gated Na+ channels open to produce a self-regenerating depolarisation."]','A','55 is the magic number — fire when you hit -55!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Neuron Anatomy & Physiology','medium','flashcard','Describe the sequence of ion channel events during an action potential.','["1) Resting: -70 mV, K+ channels open. 2) Depolarisation: voltage-gated Na+ channels open (m-gate), Na+ rushes in, membrane reaches ~+30 mV. 3) Repolarisation: Na+ channels inactivate (h-gate closes), delayed K+ channels open, K+ rushes out. 4) After-hyperpolarisation: K+ channels slow to close, membrane transiently below -70 mV. 5) Na+/K+ ATPase restores gradients."]','A','Na+ in = UP, K+ out = DOWN, Na+ inactivates = STOP','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Neuron Anatomy & Physiology','medium','flashcard','What is the absolute refractory period and why does it occur?','["A period (~1 ms) after an action potential during which NO stimulus can trigger another AP. Caused by voltage-gated Na+ channels being in the INACTIVATED state (m-gate open, h-gate closed). The h-gate must close (inactivation) then reset (closed state) before re-activation is possible."]','A','Absolute = absolutely impossible. Na+ h-gate is closed shut.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Neuron Anatomy & Physiology','medium','flashcard','What does the Na+/K+ ATPase pump do and why is it important?','["Pumps 3 Na+ OUT and 2 K+ IN per ATP. Electrogenic (net positive charge leaves cell). Maintains the ionic gradients (high Na+ outside, high K+ inside) that are essential for resting membrane potential and action potential generation."]','A','3 out, 2 in — 3 Na+ out (crowd-surfing) vs 2 K+ in','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Neuron Anatomy & Physiology','medium','flashcard','What is saltatory conduction and what enables it?','["Saltatory (jumping) conduction: action potentials jump from one Node of Ranvier to the next in myelinated axons, skipping the insulated internodal segments. Enabled by myelin sheath (produced by Schwann cells in PNS, oligodendrocytes in CNS), which increases resistance and reduces capacitance of the internodal membrane."]','A','Saltatory from Latin saltare = to jump. The AP leaps node to node!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Neuron Anatomy & Physiology','medium','flashcard','What are the two factors that determine nerve conduction velocity?','["1) Axon diameter: larger = faster (less axial resistance). 2) Myelination: myelinated = faster (saltatory conduction). Aα fibres (large, myelinated): 70-120 m/s. Aδ (small, myelinated): 5-30 m/s. C fibres (unmyelinated): 0.5-2 m/s."]','A','BIGGER and COVERED = FASTER. Like a fat, well-insulated pipe.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Neuron Anatomy & Physiology','hard','flashcard','Explain the Nernst equation for K+ and how it relates to the resting membrane potential.','["Nernst equation: EK = (RT/zF) x ln([K+]out/[K+]in) = ~61 mV x log(4/140) = approximately -94 mV. The resting membrane potential (-70 mV) is between EK (-94 mV) and ENa (+61 mV), closer to EK because K+ permeability dominates at rest. The Goldman equation (considering Na+, K+, Cl-) gives the actual resting potential."]','A','Nernst: one ion at a time equilibrium. Goldman: all ions together = reality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Neuron Anatomy & Physiology','hard','flashcard','What is the after-hyperpolarisation (AHP) and what causes it?','["AHP is the brief period after an action potential where the membrane potential goes below the resting potential (e.g., to -75 to -80 mV). Caused by: (1) Ca2+-activated K+ channels (BK/SK) opening in response to Ca2+ entry during the AP, and (2) slow closure of delayed rectifier K+ channels. AHP reduces excitability and limits firing rate."]','A','After the party (AP), the club (neuron) drops below baseline — AHP!','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Neuron Anatomy & Physiology','easy','flashcard','What is the difference between an A-alpha, A-delta, and C fibre?','["Aalpha: large, myelinated, 70-120 m/s - proprioception, motor. Abeta: medium, myelinated, 30-70 m/s - touch, pressure. Adelta: small, myelinated, 5-30 m/s - fast pain, temperature. C fibre: unmyelinated, 0.5-2 m/s - slow pain, temperature, autonomic. Mnemonic: A = Acute/fast; C = Chronic/slow."]','A','A=Acute/fast myelinated; C=Chronic/slow unmyelinated. Bigger + myelinated = FASTER.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Synaptic Transmission','easy','flashcard','What is the neurotransmitter at the neuromuscular junction and what receptor does it act on?','["Acetylcholine (ACh) acts on nicotinic ACh receptors (nAChR) — ionotropic, ligand-gated Na+/K+ channel — on the motor end plate. ACh is broken down by acetylcholinesterase in the synaptic cleft."]','A','NMJ = Nicotinic. The muscle gets tickled by ACh through a nicotinic door.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Synaptic Transmission','easy','flashcard','What is the difference between an EPSP and an IPSP?','["EPSP (excitatory postsynaptic potential): depolarisation of the postsynaptic membrane, moving toward threshold. Caused by opening of cation channels (Na+ in or K+ out or Ca2+ in). IPSP (inhibitory postsynaptic potential): hyperpolarisation, moving away from threshold. Caused by Cl- influx (GABA-A, glycine) or K+ efflux (GABA-B via GIRK)."]','A','EPSP = Exciting (depolarises). IPSP = Inhibiting (hyperpolarises). E vs I!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Synaptic Transmission','medium','flashcard','What is the difference between spatial and temporal summation?','["Spatial summation: multiple presynaptic neurons fire simultaneously, their EPSPs add together at the postsynaptic neuron to reach threshold. Temporal summation: one presynaptic neuron fires repeatedly in rapid succession before the previous EPSP decays, and the potentials accumulate."]','A','Space = multiple places at once. Time = same place rapidly repeated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Synaptic Transmission','medium','flashcard','What are the 5 steps of chemical synaptic transmission?','["1) Action potential reaches presynaptic terminal. 2) Voltage-gated Ca2+ channels open, Ca2+ enters. 3) Ca2+ triggers vesicle docking and fusion with membrane (SNARE proteins). 4) Neurotransmitter released into synaptic cleft by exocytosis. 5) NT binds to postsynaptic receptors, causing EPSP or IPSP."]','A','Ca2+ = the key that opens the NT door. No Ca2+ = no release.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Synaptic Transmission','medium','flashcard','What is the difference between ionotropic and metabotropic receptors?','["Ionotropic: ligand-gated ion channels. Fast (milliseconds). NT binds and directly opens an ion channel. Examples: AMPA, NMDA, GABA-A, nicotinic ACh, glycine. Metabotropic: G-protein coupled receptors (GPCRs). Slow (seconds-minutes). NT binds, activates G-protein, which modulates ion channels or enzymes via second messengers. Examples: muscarinic, mGluR, GABA-B, adrenergic."]','A','Iono = IMMEDIATE (the door IS the channel). Metro = SLOW (G-protein middleman).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Synaptic Transmission','medium','flashcard','What is the NMDA receptor and why is it called a coincidence detector?','["NMDA receptor: ionotropic glutamate receptor that is BOTH ligand-gated (needs glutamate AND glycine co-agonist) AND voltage-gated (needs membrane depolarisation to relieve Mg2+ block at resting potential). It can only activate when BOTH conditions are met simultaneously — coincidence detection. When open, allows Ca2+ and Na+ influx. Critical for LTP, learning, and memory."]','A','NMDA = Needs More Depolarisation to Activate. Double lock: glutamate + voltage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Synaptic Transmission','medium','flashcard','What is presynaptic inhibition and how does it differ from postsynaptic inhibition?','["Presynaptic inhibition: an axo-axonic synapse where an inhibitory neuron (releasing GABA-B or adenosine) acts on the presynaptic terminal, reducing Ca2+ influx and thereby decreasing NT release. Postsynaptic inhibition: IPSPs directly hyperpolarise the postsynaptic membrane via Cl- influx (GABA-A, glycine). Presynaptic inhibition selectively inhibits specific inputs without affecting the postsynaptic neuron itself."]','A','Pre-synaptic = block delivery. Post-synaptic = block reception.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Synaptic Transmission','hard','flashcard','What molecular steps are required for long-term potentiation (LTP) at Schaffer collaterals?','["1) High-frequency stimulation activates AMPA receptors on CA1 neurons, causing depolarisation. 2) Depolarisation removes Mg2+ block from NMDA receptors. 3) NMDA receptors open, Ca2+ influx into CA1 dendrites. 4) Ca2+ activates CaMKII (Ca2+/calmodulin-dependent kinase II). 5) CaMKII phosphorylates existing AMPA receptors (increasing conductance) and triggers insertion of new AMPA receptors. 6) Retrograde messengers (NO, endocannabinoids) increase presynaptic glutamate release. Result: stronger, more efficient synapse."]','A','AMPA depolarises, NMDA gates Ca2+, CaMKII does the potentiation!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Synaptic Transmission','hard','flashcard','What is quantal release of neurotransmitter and how was it discovered?','["Quantal release: neurotransmitters are released in discrete packets (quanta), each quantum corresponding to the contents of one synaptic vesicle (~5,000-10,000 molecules). Discovered by Fatt and Katz (1952) via miniature end-plate potentials (MEPPs): spontaneous ~0.5 mV depolarisations at the NMJ representing spontaneous fusion of single vesicles. An evoked EPSP = sum of many quanta (N x quantum size)."]','A','Each vesicle is one coin. MEPPs are the coins falling one at a time.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Synaptic Transmission','easy','flashcard','What is the role of acetylcholinesterase at the synapse?','["Acetylcholinesterase (AChE) rapidly degrades acetylcholine in the synaptic cleft into choline and acetate, terminating the signal. Choline is taken back up by the presynaptic terminal and recycled to make new ACh. AChE inhibitors (neostigmine, physostigmine, organophosphates) prolong ACh action — used in myasthenia gravis treatment; dangerous in poisoning."]','A','AChE STOPS the music by breaking up ACh. Inhibit it = more ACh = more music.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sensory Systems','easy','flashcard','What modalities does the dorsal column-medial lemniscal (DCML) pathway carry?','["Fine touch, vibration sense, two-point discrimination, and proprioception (conscious). The pathway is IPSILATERAL in the spinal cord (first-order neurons ascend in dorsal columns), decussates in the MEDULLA (nucleus gracilis/cuneatus), then ascends as medial lemniscus to VPL thalamus, then to somatosensory cortex."]','A','DC-ML = Don''''t Cross till Medulla Level. Fine touch stays same side to medulla.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sensory Systems','easy','flashcard','What modalities does the spinothalamic tract (anterolateral system) carry?','["Pain, temperature (and crude touch). First-order neurons enter the spinal cord, synapse in the dorsal horn (lamina I, II, V). Second-order neurons cross immediately in the ANTERIOR COMMISSURE within 1-2 spinal segments, then ascend CONTRALATERALLY to VPL thalamus, then to somatosensory cortex."]','A','Spinothalamic = STOP and Cross: pain fibres cross at the LEVEL of entry.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sensory Systems','medium','flashcard','Explain the gate control theory of pain.','["Melzack and Wall (1965): pain transmission is modulated in the dorsal horn spinal cord. Large Abeta fibres (touch) activate inhibitory interneurons (substantia gelatinosa, lamina II) that close the gate on pain signals from Adelta and C fibres. Small C fibres open the gate. This explains why rubbing a painful area reduces pain (activates Abeta fibres). It is the basis for TENS (transcutaneous electrical nerve stimulation)."]','A','Rub the boo-boo to close the gate! Abeta = gate-closer, C fibres = gate-opener.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sensory Systems','medium','flashcard','What is referred pain and what is the neurological mechanism?','["Referred pain: pain perceived at a site distant from the actual source of injury. Mechanism: convergence-projection theory — visceral afferents and somatic afferents converge onto the same second-order dorsal horn neurons. The brain misattributes the signal to the somatic distribution. Examples: MI = left arm/jaw pain (T1-T5 convergence); appendicitis = periumbilical then RIF; diaphragm irritation = shoulder pain (C3-C5, phrenic nerve)."]','A','Heart pain = LEFT ARM: visceral and somatic meet in the same spinal post-code.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sensory Systems','medium','flashcard','What is a dermatome and name 5 clinically important landmarks.','["A dermatome = area of skin innervated by a single spinal nerve root. Key landmarks: C4 = cape of shoulders; T4 = nipple level; T10 = umbilicus; L1 = groin/inguinal ligament; L4 = medial leg to big toe; S1 = lateral foot/little toe; S4/S5 = perineum (saddle area). Dermatomes overlap: a single root lesion rarely causes complete anaesthesia."]','A','T4 = Tit, T10 = Tummy button, S4 = Saddle (S for Seat).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sensory Systems','medium','flashcard','What is the somatosensory homunculus and what does it represent?','["The sensory homunculus is a map of the body in primary somatosensory cortex (S1, postcentral gyrus). Cortical area is proportional to sensory discriminatory ability (receptor density), NOT body size. Disproportionately large areas: hands, lips, tongue, face. The face is lateral, the leg is medial on the superior cortex. Contralateral representation."]','A','Big lips, big hands on the little man — high discrimination = big cortical space.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sensory Systems','medium','flashcard','What are the two types of pain fibres and the pain they convey?','["Adelta fibres (myelinated, type III, 5-30 m/s): fast/first pain — sharp, well-localised, pricking sensation. Activates neospinothalamic tract. C fibres (unmyelinated, type IV, 0.5-2 m/s): slow/second pain — burning, dull, diffuse, chronic. Activates paleospinothalamic tract (projects to reticular formation and medial thalamus). Double pain response after injury: Adelta first, C fibres second."]','A','Hit your finger: FIRST ouch (Adelta) then THROBBING ache (C fibre).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sensory Systems','hard','flashcard','Describe the endogenous analgesic system (descending pain modulation).','["The periaqueductal grey (PAG) receives input from the cortex, hypothalamus, and amygdala. PAG neurons activate: (1) serotonergic neurons of the raphe magnus (→ spinal dorsal horn inhibition), (2) noradrenergic neurons of the locus coeruleus. These inhibit pain transmission in the dorsal horn via enkephalins and dynorphins (endogenous opioids). Exogenous opioids (morphine) mimic endogenous enkephalins."]','A','PAG = Pain Abatement Gate. Raphe = serotonin; LC = noradrenaline. Both stop pain.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sensory Systems','hard','flashcard','What is the difference between allodynia and hyperalgesia?','["Allodynia: pain in response to a normally non-painful stimulus (e.g., light touch causes pain). Hyperalgesia: exaggerated pain response to a normally painful stimulus. Primary hyperalgesia (at injury site): peripheral sensitisation — prostaglandins, bradykinin, and substance P lower nociceptor threshold. Secondary hyperalgesia (beyond injury): central sensitisation — wind-up and NMDA receptor-mediated amplification in the dorsal horn."]','A','Allodynia: touch = ouch. Hyperalgesia: ouch = OUCH! Primary = peripheral; Secondary = central.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sensory Systems','easy','flashcard','What is the function of the VPL and VPM nuclei of the thalamus in sensory processing?','["VPL (ventral posterolateral nucleus): relay nucleus for somatosensory information from the BODY — receives input from the spinothalamic tract and medial lemniscus, projects to primary somatosensory cortex (S1). VPM (ventral posteromedial nucleus): relay for somatosensory and taste information from the FACE — receives input from the trigeminal pathway (CN V) and solitary nucleus."]','A','VPL = body, VPM = mug (face). Both project to S1.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Motor Systems','easy','flashcard','List the key differences between UMN and LMN lesions.','["UMN lesion: spastic paralysis, increased tone (clasp-knife rigidity), hyperreflexia, clonus, Babinski sign (extensor plantar response), no muscle atrophy (or minimal disuse atrophy). LMN lesion: flaccid paralysis, decreased tone, hyporeflexia/areflexia, fasciculations, muscle atrophy (denervation), fibrillations on EMG."]','A','UMN = UPPER = Upright tone, Upgoing toe. LMN = LOWER = Limp, Loose, atrophied.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Motor Systems','easy','flashcard','Where does the corticospinal tract decussate and why is this clinically important?','["Approximately 85% of corticospinal fibres decussate at the pyramidal decussation in the caudal medulla to form the lateral corticospinal tract. Therefore, lesions ABOVE the decussation (cortex, internal capsule, brainstem) cause CONTRALATERAL weakness. Lesions BELOW (spinal cord, anterior horn) cause IPSILATERAL weakness."]','A','Decussation in medulla: lesion above = opposite side weak.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Motor Systems','medium','flashcard','Describe the direct and indirect pathways of the basal ganglia and their net effect on movement.','["Direct pathway (movement facilitator): Cortex activates striatum (D1) → striatum INHIBITS GPi/SNpr → thalamus DISINHIBITED → cortex ACTIVATED = MORE movement. Indirect pathway (movement inhibitor): Cortex activates striatum (D2) → striatum INHIBITS GPe → GPe LESS INHIBITS STN → STN ACTIVATES GPi/SNpr → thalamus INHIBITED → less movement. Dopamine: facilitates direct (D1) and inhibits indirect (D2) = net pro-movement effect."]','A','Direct = FAST GO. Indirect = SLOW STOP. Dopamine says GO!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Motor Systems','medium','flashcard','What are the signs of a dominant hemisphere MCA stroke?','["Contralateral face and arm greater than leg weakness and sensory loss (MCA distribution spares leg, which is ACA territory). PLUS: Broca aphasia (frontal operculum lesion = non-fluent, good comprehension) or Wernicke aphasia (temporal lesion = fluent, poor comprehension) or global aphasia (large MCA). Plus homonymous hemianopia (optic radiation). Plus ipsilateral gaze preference (eyes look toward lesion = frontal eye field damage)."]','A','MCA face/arm, ACA leg — aphasia if dominant, neglect if non-dominant.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Motor Systems','medium','flashcard','What is the role of the supplementary motor area (SMA) in motor control?','["The SMA (medial part of Brodmann area 6) is active during mentally rehearsing or initiating self-generated voluntary movements (even before movement onset — Bereitschaftspotential). It is important for programming sequences of movements. SMA lesions cause difficulty initiating movements, alien hand syndrome, and impaired bi-manual coordination. It receives direct cortical-cortical input and projects to primary motor cortex."]','A','SMA = plans movements BEFORE they happen. Damage = can''''t START.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Motor Systems','medium','flashcard','What is the gamma motor neuron and how does it regulate muscle spindle sensitivity?','["Gamma motor neurons (Ay efferents) innervate the polar (contractile) ends of intrafusal muscle fibres in the muscle spindle. They do NOT contribute to force production. They ADJUST the sensitivity of the muscle spindle by maintaining tension on the equatorial (sensory) region during muscle contraction. High gamma activity = high spindle sensitivity = strong stretch reflex = increased muscle tone."]','A','Gamma = the spindle tuner. Like adjusting microphone sensitivity for better signal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Motor Systems','medium','flashcard','What is a Babinski sign and what does it indicate?','["Babinski sign: extension (dorsiflexion) of the big toe and fanning of the other toes in response to stroking the lateral plantar surface of the foot. Positive Babinski = UMN lesion (corticospinal tract damage). Normal in infants (up to 2 years) before corticospinal myelination is complete. An extension response (also called an extensor plantar response). Lesion is typically above the anterior horn."]','A','Babinski = Big toe goes UP = BAD (UMN lesion). Baby = normal (not myelinated yet).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Motor Systems','hard','flashcard','Explain the pathophysiology of Huntington disease in terms of basal ganglia circuitry.','["HD: autosomal dominant, CAG trinucleotide repeat expansion in HTT gene on chromosome 4, encoding polyglutamine tract in huntingtin protein. Early selective loss of indirect pathway medium spiny neurons (D2/enkephalin+) in caudate/putamen. Loss of indirect pathway → decreased GPi/SNpr activity → thalamic disinhibition → excessive cortical drive → CHOREA. Later, direct pathway neurons also lost → hypokinesia, rigidity, dementia."]','A','HD: indirect pathway dies first = chorea. Both die = rigidity late.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Motor Systems','hard','flashcard','What is the role of the red nucleus and rubrospinal tract?','["Red nucleus: in the midbrain tegmentum, receives input from the contralateral dentate nucleus (via superior cerebellar peduncle) and corticorubral fibres. Gives rise to the rubrospinal tract, which decussates in the midbrain and descends to the spinal cord. In humans, the rubrospinal tract is small and less important than in other mammals. Primarily modulates distal limb movements and serves as an alternative motor pathway when the corticospinal tract is damaged."]','A','Red nucleus = cerecorticospinal backup. It gets crossed dental info = control opposite limb.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Motor Systems','easy','flashcard','What are the signs of a pure motor lacunar stroke?','["Pure motor stroke (lacunar infarct): typically involves the posterior limb of the internal capsule or base of pons. Presents as contralateral hemiplegia (face, arm, leg equally affected) WITHOUT sensory deficit, visual field defect, or higher cortical dysfunction (aphasia, neglect). Caused by small vessel disease (lipohyalinosis) of the lenticulostriate arteries. Common in hypertension."]','A','PURE MOTOR: face-arm-leg equally weak, NOTHING else. Internal capsule or pons.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebellum','easy','flashcard','Why are cerebellar lesions ipsilateral (same side)?','["The cerebellum undergoes double-decussation: cerebellar efferents (from deep nuclei) cross via the superior cerebellar peduncle to the contralateral thalamus/red nucleus, which cross again as the corticospinal tract. Net result: cerebellar hemisphere controls ipsilateral limb movements. So right cerebellar lesion = right-sided ataxia."]','A','Cerebellum double-crosses: twice crossed = same side. Right cerebellum = right arm.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebellum','easy','flashcard','What are the three functional divisions of the cerebellum and their functions?','["1) Vestibulocerebellum (flocculonodular lobe, archicerebellum): equilibrium and eye movements. 2) Spinocerebellum (vermis + intermediate hemisphere): gait and limb coordination. 3) Cerebrocerebellum (lateral hemispheres, neocerebellum): planning and timing of complex voluntary movements."]','A','Vestibulo = Balance. Spino = movement correction. Cerebro = Timing/planning.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebellum','medium','flashcard','What are the classic signs of cerebellar dysfunction (DANISH)?','["D = Dysdiadochokinesia (impaired rapid alternating movements). A = Ataxia (gait, truncal, or limb). N = Nystagmus (fast phase away from lesion). I = Intention tremor (tremor that worsens on approach to target — in contrast to rest tremor in Parkinson). S = Slurred speech (dysarthria, scanning speech). H = Hypotonia. DANISH or DASHING — key cerebellar signs."]','A','DANISH! Dysdiadochokinesia, Ataxia, Nystagmus, Intention tremor, Speech, Hypotonia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebellum','medium','flashcard','What is the functional significance of Purkinje cells?','["Purkinje cells: the sole output of the cerebellar cortex. Large, GABA-ergic (inhibitory) neurons with enormous dendritic trees that receive up to 200,000 parallel fibre (granule cell) synapses each. They inhibit the deep cerebellar nuclei (DCN). Deep nuclei fire continuously; Purkinje cells modulate this by increasing or decreasing inhibition. By disinhibiting DCN, the cerebellum can drive its motor outputs."]','A','Purkinje = the BOSS of cortex output. GABAergic = the great inhibitor of deep nuclei.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebellum','medium','flashcard','What is the difference between mossy fibres and climbing fibres in the cerebellum?','["Mossy fibres: arise from spinal cord, pontine nuclei, vestibular nuclei. Each mossy fibre contacts many granule cells via glomeruli. Granule cells (smallest, most numerous neurons in CNS) project axons as parallel fibres to contact thousands of Purkinje cells. Provide multi-modal sensory and motor input. Climbing fibres: arise EXCLUSIVELY from inferior olivary nucleus. Each climbing fibre contacts ONE Purkinje cell with powerful, all-or-nothing activation. Carry motor error signals for learning."]','A','Mossy = spreading, many contacts. Climbing = 1-to-1 powerful error signal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebellum','medium','flashcard','What is cerebellar dysmetria and how do you test for it?','["Dysmetria: inability to judge distance/extent of movement accurately — movements either overshoot (hypermetria) or undershoot (hypometria) the target. Tests: finger-nose-finger test (patient touches own nose then examiner''''s finger repeatedly — look for past-pointing), heel-shin test (heel placed on contralateral knee, slides down shin — look for wavering). Ipsilateral to cerebellar lesion."]','A','Dysmetria: Miss the mark! Finger-nose test: wave hello instead of hitting target.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebellum','hard','flashcard','What is the cerebellar learning hypothesis (Marr-Albus-Ito)?','["Long-term depression (LTD) at parallel fibre synapses: when a parallel fibre and a climbing fibre (error signal) co-activate the SAME Purkinje cell simultaneously, the parallel fibre synapse undergoes LTD — it becomes WEAKER. This occurs via: co-activation → Ca2+ rise → PKC activation → AMPA receptor dephosphorylation/removal. Weakened Purkinje cell inhibition of deep nucleus = enhanced motor output through that pathway. Over many trials, the error signal decreases and movement improves."]','A','Error signal (climbing fibre) + movement attempt (parallel fibre) = LTD = learning.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebellum','hard','flashcard','What is the anatomical basis of tandem gait ataxia in vermis lesions?','["The cerebellar vermis (spinocerebellum) controls the axial musculature and proximal limb movements via projections to the fastigial nucleus and vestibular nuclei, which control spinal interneurons via vestibulospinal and reticulospinal tracts. Vermis lesions impair axial coordination → truncal ataxia → wide-based, staggering, tandem gait failure. Limbs may be relatively unaffected (lateral hemisphere spared)."]','A','Vermis = midline = axial/gait control. Lateral = limb dexterity. Vermis damage = drunk walk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebellum','easy','flashcard','Through which cerebellar peduncle do most cerebellar efferents exit?','["Superior cerebellar peduncle (brachium conjunctivum): the primary OUTPUT pathway of the cerebellum. Carries fibres from deep cerebellar nuclei (especially dentate and interposed) to the contralateral thalamus (VL) and red nucleus. The middle cerebellar peduncle (largest) carries INPUT from the pontine nuclei. The inferior cerebellar peduncle carries input from the spinal cord and vestibular system."]','A','Superior = the EXIT. Middle = the MOTORWAY in. Inferior = spinal/vestibular inputs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebellum','easy','flashcard','What is dysdiadochokinesia and what does it indicate?','["Dysdiadochokinesia: impaired ability to perform rapid alternating movements (e.g., rapid pronation/supination of the forearm). Indicates cerebellar dysfunction — specifically the lateral hemisphere/cerebrocerebellum. Tested by having the patient rapidly pat the back of one hand with the palm and dorsum of the other hand alternately."]','A','Dysdiadochokinesia: can''''t drum fast hands = cerebellar sign. The big word everyone loves.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Brainstem & Cranial Nerves','easy','flashcard','List the cranial nerves by number and name (CN I-XII).','["I Olfactory, II Optic, III Oculomotor, IV Trochlear, V Trigeminal, VI Abducens, VII Facial, VIII Vestibulocochlear, IX Glossopharyngeal, X Vagus, XI Accessory, XII Hypoglossal. Mnemonic: Oh Oh Oh To Touch And Feel Very Good Velvet AH! (or On Old Olympus Towering Top A Finn And German Viewed Some Hops)."]','A','OOO TT AFVG VS H — Oh Oh Oh Touch That A Famous Very Good Vein''''s Stem Hook.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Brainstem & Cranial Nerves','easy','flashcard','What is the rule of 4 for brainstem cranial nerve localisation?','["Rule of 4: (1) 4 cranial nerves in the midbrain (CN III, IV from midbrain). (2) 4 in the pons (CN V, VI, VII, VIII). (3) 4 in the medulla (CN IX, X, XI, XII). Also: 4 cranial nerve nuclei near the midline (motor), 4 further out (sensory), 4 brainstem syndromes. If you see CN III — think midbrain. CN VII/VIII — pons."]','A','3 groups of 4: Midbrain 3+4, Pons 5-8, Medulla 9-12.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Brainstem & Cranial Nerves','medium','flashcard','What is Wallenberg syndrome (lateral medullary syndrome)?','["PICA (posterior inferior cerebellar artery) occlusion. Ipsilateral findings: (1) facial pain/temperature loss (CN V spinal nucleus), (2) Horner syndrome (descending sympathetics), (3) limb/gait ataxia (cerebellum/ICP), (4) dysphagia/hoarseness/hiccups (CN IX/X nuclei), (5) vertigo/nausea (vestibular nuclei). Contralateral: body pain/temperature loss (spinothalamic tract). Crossed sensory pattern is pathognomonic."]','A','Wallenberg = PICA = crossed face/body sensation. Ipsilateral face, contralateral body.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Brainstem & Cranial Nerves','medium','flashcard','Explain pupillary light reflex and the anatomy of the pathway.','["Light into one eye → afferent CN II (optic nerve) → pretectal nucleus (midbrain) → BOTH Edinger-Westphal nuclei → efferent CN III (parasympathetic) → ciliary ganglion → short ciliary nerves → sphincter pupillae → both pupils constrict. Direct response: same eye. Consensual response: other eye. A relative afferent pupillary defect (RAPD/Marcus Gunn pupil): swinging flashlight test positive — CN II lesion on affected side."]','A','Light in → both eyes constrict. CN II takes it IN, CN III takes action OUT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Brainstem & Cranial Nerves','medium','flashcard','What is the clinical presentation of CN III palsy and what structures can compress it?','["CN III palsy: (1) Ptosis (LPS innervation lost), (2) Mydriasis (pupil-involving: parasympathetic fibres on the OUTSIDE of CN III compressed first), (3) Eye deviated DOWN and OUT (lateral rectus CN VI + superior oblique CN IV unopposed). Causes: posterior communicating artery (PCoA) aneurysm (pupil-sparing early is BAD sign of compression), uncal herniation (compresses CN III), DM (pupil-SPARING, ischaemia of the core of the nerve)."]','A','DOWN and OUT = LR6 SO4 R3 — only CN VI and IV left working. Aneurysm = pupil first!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Brainstem & Cranial Nerves','medium','flashcard','What is internuclear ophthalmoplegia (INO) and what causes it?','["INO: lesion of the medial longitudinal fasciculus (MLF). On attempted lateral gaze toward the lesion side: impaired ADDUCTION of ipsilateral eye (CN III cannot be activated via MLF) + nystagmus of the abducting contralateral eye. Vertical gaze is preserved. Bilateral INO in a young patient = multiple sclerosis. Unilateral INO in an older patient = brainstem stroke."]','A','MLF = the phone line between VI and III. Cut it = the eyes can''''t talk to each other.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Brainstem & Cranial Nerves','medium','flashcard','What are the functions of CN VII (facial nerve)?','["Motor: facial expression muscles (upper and lower face), stapedius, stylohyoid, posterior digastric. Sensory (taste): anterior 2/3 of tongue via chorda tympani → nucleus solitarius. Sensory (general): small area of ear (nervus intermedius). Parasympathetic: lacrimal glands (via greater petrosal nerve), submandibular and sublingual glands (via chorda tympani and submandibular ganglion). Mnemonic: Facial (motor), Taste (anterior 2/3), Salivary (submandibular/sublingual), Lacrimal."]','A','CN VII: face, taste (anterior 2/3), tears, saliva. FTTS = Facial, Taste, Tears, Saliva.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Brainstem & Cranial Nerves','hard','flashcard','What is the difference between a central and peripheral CN VII (facial nerve) palsy?','["Peripheral CN VII palsy (Bell palsy, parotid tumour): ALL muscles of facial expression on the ipsilateral side are weak — including the FOREHEAD. This is because the lower motor neurons supply ALL ipsilateral facial muscles. Central CN VII palsy (UMN lesion, e.g., stroke above the pons): contralateral lower face weakness but FOREHEAD IS SPARED because the forehead receives bilateral cortical innervation (upper face has bilateral UMN input)."]','A','Central = forehead SPARED. Peripheral = forehead FLATTENED. Forehead = tells you where!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Brainstem & Cranial Nerves','hard','flashcard','What is Weber syndrome and how does it differ from Benedikt syndrome?','["Weber syndrome: ventral midbrain tegmentum. CN III fascicle (ipsilateral CN III palsy: ptosis, mydriasis, down-and-out eye) + cerebral peduncle (contralateral spastic hemiplegia). Benedikt syndrome: more dorsal midbrain. CN III fascicle (ipsilateral CN III palsy) + red nucleus (contralateral tremor/choreoathetosis/ataxia, NO hemiplegia). Mnemonic: Weber = Weakness (corticospinal tract). Benedikt = Bowing/tremor (red nucleus)."]','A','Weber = CN III + Weakness (contralateral). Benedikt = CN III + Bumbling (tremor).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Brainstem & Cranial Nerves','easy','flashcard','What does CN IX (glossopharyngeal nerve) do?','["Sensory: posterior 1/3 of tongue (taste and general sensation), pharynx (gag reflex afferent), carotid body/sinus (chemoreceptors and baroreceptors). Motor: stylopharyngeus (elevates pharynx). Parasympathetic: parotid gland (via lesser petrosal nerve and otic ganglion). Clinical: loss of gag reflex (CN IX afferent, CN X efferent). Jugular foramen syndrome involves CN IX, X, XI together."]','A','Nine = posterior 1/3 tongue + gag afferent + parotid + carotid body.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Limbic System & Memory','easy','flashcard','What is the role of the hippocampus in memory and what type of amnesia occurs with bilateral lesions?','["The hippocampus converts short-term memories into long-term declarative memories (memory consolidation). Bilateral hippocampal lesions cause ANTEROGRADE AMNESIA: inability to form new long-term declarative memories. Remote (long-term) memories formed before the lesion are relatively preserved (stored in cortex). Working memory is intact. Example: patient H.M. (Henry Molaison) after bilateral temporal lobectomy."]','A','Hippo = converts short to long-term. Destroy it = can''''t make NEW memories.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Limbic System & Memory','easy','flashcard','What is the Papez circuit and what are its components?','["Papez circuit (1937): Hippocampus → Fornix → Mammillary bodies → Anterior thalamus (via mammillothalamic tract) → Cingulate cortex → Entorhinal cortex → Hippocampus. Function: emotional experience and memory consolidation. Damage (e.g., Wernicke-Korsakoff, viral encephalitis): amnesia and emotional disturbance."]','A','Hippie Forgets Mama After Cingulate Enrols them. HF-MA-CE. Papez = emotion + memory.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Limbic System & Memory','medium','flashcard','Compare declarative (explicit) and non-declarative (implicit) memory systems.','["Declarative (explicit) memory: conscious recollection. Requires hippocampus. Types: Episodic (personal events, when/where) and Semantic (facts, knowledge). Non-declarative (implicit) memory: unconscious. Types: Procedural/skill learning (basal ganglia, cerebellum), Priming (neocortex), Classical conditioning of fear (amygdala), Habituation/sensitisation (reflex circuits). Preserved in hippocampal amnesia!"]','A','Explicit = can EXPLAIN it (hippo needed). Implicit = can''''t explain but can DO it.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Limbic System & Memory','medium','flashcard','What is Wernicke-Korsakoff syndrome: cause, presentation, and pathology?','["Cause: thiamine (B1) deficiency, classically in alcoholics. Wernicke encephalopathy (reversible if treated): triad of ophthalmoplegia (nystagmus, CN VI palsy), cerebellar ataxia, and confusion. Pathology: haemorrhagic lesions in periventricular structures — mammillary bodies, periaqueductal grey, dorsomedial thalamus. Korsakoff psychosis (often irreversible): anterograde amnesia, retrograde amnesia, and CONFABULATION (fabricating memories without intent to deceive)."]','A','Wernicke = ophthalmoplegia + ataxia + confusion. Korsakoff = amnesia + confabulation. Give B1!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Limbic System & Memory','medium','flashcard','What is the role of the amygdala in emotional memory?','["The amygdala (basolateral and central nuclei) assigns emotional significance to stimuli and is critical for FEAR CONDITIONING. It receives sensory input (direct thalamic shortcut for fast responses, and cortical input for slow, accurate responses). Fear memory: amygdala stores the emotional tag; hippocampus stores contextual details. Amygdala damage: inability to condition fear, difficulty recognising fearful expressions. Kluver-Bucy syndrome (bilateral amygdala): emotional blunting, hypersexuality, hyperorality, visual agnosia."]','A','Amygdala = FEAR alarm system. Kluver-Bucy (bilateral destruction) = calm, hypersexual, eats everything.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Limbic System & Memory','medium','flashcard','What is Kluver-Bucy syndrome?','["Kluver-Bucy syndrome: caused by bilateral amygdala (and anterior temporal lobe) destruction. Features: (1) Hyperorality (putting objects in mouth), (2) Hypersexuality, (3) Visual agnosia (inability to recognise objects by sight — psychic blindness), (4) Placidity/emotional blunting (fearlessness), (5) Dietary changes (hyperphagia). Causes in humans: herpes simplex encephalitis (bilateral temporal lobe), severe temporal lobe trauma, Pick disease."]','A','Kluver-Bucy: lost amygdala = lost fear = placid, hypersexual, puts everything in mouth.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Limbic System & Memory','medium','flashcard','What is the difference between anterograde and retrograde amnesia?','["Anterograde amnesia: inability to form NEW long-term memories after the lesion. Retrograde amnesia: loss of memories BEFORE the lesion. Typically follows a temporal gradient (recent memories lost first, remote memories best preserved — Ribot''''s law). Hippocampal lesions primarily cause anterograde amnesia. Extended retrograde amnesia suggests more extensive limbic system damage or diencephalic damage."]','A','Anterograde = can''''t go forward (can''''t make new). Retrograde = goes backward (lost old ones).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Limbic System & Memory','hard','flashcard','What is long-term potentiation (LTP) and why is it important for memory?','["LTP: activity-dependent strengthening of synaptic connections. Key mechanisms: 1) NMDA receptor-dependent LTP (most important for memory) — requires co-activation of AMPA and NMDA receptors, Ca2+ influx, CaMKII activation, and AMPA receptor upregulation. 2) NMDA-independent LTP (mGluR/PKC-dependent). LTP is the cellular correlate of learning and memory formation. Blocking NMDA receptors in rodents impairs spatial learning (Morris water maze)."]','A','LTP = stronger synapse = better memory. NMDA receptor is the key trigger.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Limbic System & Memory','hard','flashcard','What is the default mode network (DMN) and how is it related to limbic function?','["The DMN is a network of brain regions active during rest and self-referential thought: medial prefrontal cortex, posterior cingulate cortex, precuneus, angular gyrus, hippocampus. It is deactivated during focused external tasks. The DMN integrates episodic memory retrieval, autobiographical memory, theory of mind, and imagining future events. DMN disruption is prominent in Alzheimer disease (posterior cingulate and hippocampal atrophy)."]','A','DMN = day-dreaming network. Brain''''s resting background hum. AD disrupts it early.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Limbic System & Memory','easy','flashcard','What is confabulation and in which condition is it classically seen?','["Confabulation: production of fabricated, distorted, or misinterpreted memories about oneself or the world, WITHOUT conscious intent to deceive. Patient genuinely believes the false memory. Classically seen in Korsakoff syndrome (thiamine deficiency, mammillary body damage). Also in: severe frontal lobe damage, dementia, anoxic brain injury. It is thought to arise from inability to monitor and reject false memories (frontal-hippocampal disconnection)."]','A','Confabulation = brain makes up stories but doesn''''t know it''''s lying. Korsakoff classic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Autonomic Nervous System','easy','flashcard','What is the key difference between sympathetic and parasympathetic neurotransmitters at the effector organ?','["Sympathetic postganglionic: releases NOREPINEPHRINE (NE) onto adrenergic receptors (alpha and beta). Exception: sweat glands (cholinergic). Parasympathetic postganglionic: releases ACETYLCHOLINE (ACh) onto muscarinic receptors. ALL preganglionic neurons (both divisions): release ACh onto nicotinic receptors. Adrenal medulla: releases epinephrine (80%) and NE (20%) into blood."]','A','Pre-ganglionic BOTH use ACh. Post-ganglionic: Parasympathetic = ACh (muscarinic); Sympathetic = NE.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Autonomic Nervous System','easy','flashcard','What are the alpha and beta adrenergic receptors and their main effects?','["Alpha1: vasoconstriction (smooth muscle), mydriasis, urinary retention, decreased gut motility. Alpha2: presynaptic feedback inhibition, platelet aggregation, insulin inhibition. Beta1: increased HR and contractility (heart), renin release (kidney). Beta2: bronchodilation, vasodilation in skeletal muscle, glycogenolysis, uterine relaxation. Beta3: lipolysis in adipose tissue."]','A','Alpha1 = vasoconstriction. Beta1 = heart (1 heart). Beta2 = lungs + vessels (2 lungs).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Autonomic Nervous System','medium','flashcard','Describe the physiological effects of parasympathetic activation (rest and digest).','["Heart: decreased HR (M2 via IK-ACh), decreased AV conduction. Lungs: bronchoconstriction (M3), increased secretion. GI: increased motility, relaxed sphincters, increased secretion. Bladder: detrusor contraction (M3), urination facilitated. Eyes: miosis (M3, sphincter pupillae), accommodation for near vision (ciliary muscle). Salivation/lacrimation increased. Erection (''''point'''' = parasympathetic)."]','A','Rest and digest: slow heart, open gut, contract bladder, small pupil. ''''SLUDD'''' = salivation, lacrimation, urination, defecation, digestion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Autonomic Nervous System','medium','flashcard','What is Horner syndrome and what are the three components?','["Horner syndrome: disruption of the sympathetic supply to the eye. Triad: (1) Ptosis (partial, LPS weakness — sympathetics innervate superior tarsal muscle of Muller), (2) Miosis (pupil constriction — unopposed parasympathetics; iris dilator paralysed), (3) Anhidrosis (loss of sweating on ipsilateral face, if post-ganglionic fibre involved). (+/- enophthalmos, apparent). 3-neuron pathway: hypothalamus (1st order) → T1-T2 cord (2nd order) → superior cervical ganglion → carotid plexus (3rd order)."]','A','Horner = PMA: Ptosis, Miosis, Anhidrosis. Sympathetic pathway cut.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Autonomic Nervous System','medium','flashcard','What is the sympathetic storm and when does it occur?','["Sympathetic storm (also autonomic dysreflexia in spinal cord injury above T6): massive, uncontrolled sympathetic discharge below the level of the spinal lesion in response to a noxious stimulus (e.g., bladder distension). Presents: severe hypertension (vasoconstriction below lesion), bradycardia (baroreceptor reflex), headache, flushing/sweating above the lesion (compensatory). Potentially fatal. Treatment: remove the stimulus, upright positioning, antihypertensives."]','A','Spinal cord injury above T6 + full bladder = Sympathetic EXPLOSION. BP through the roof!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Autonomic Nervous System','medium','flashcard','What are the muscarinic receptor subtypes and their signalling mechanisms?','["M1 (Gq): CNS, gastric parietal cells. IP3/DAG → Ca2+ → secretion/depolarisation. M2 (Gi): heart (SA/AV nodes). Decreased cAMP + GIRK channel activation → bradycardia/hypotension. M3 (Gq): smooth muscle, glands. IP3 → Ca2+ → contraction/secretion. M4 (Gi): CNS. M5 (Gq): CNS, cerebral vessels. Clinically: M2 = cardiac slowing; M3 = bronchospasm, bowel cramps, urination."]','A','M2 = heart (Gi = slow). M3 = smooth muscle/glands (Gq = squeeze). M1 = brain/stomach.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Autonomic Nervous System','medium','flashcard','Why does atropine cause mydriasis, tachycardia, and dry mouth?','["Atropine: non-selective muscarinic (M1-M5) antagonist. Blocks: M3 on iris sphincter → mydriasis (pupil dilation). M3 on salivary glands → dry mouth (xerostomia). M3 on bronchioles → bronchodilation. M2 on SA node → tachycardia (removes vagal brake). M3 on GI → decreased motility, constipation. Mnemonic: Blind as a bat (mydriasis), Dry as a bone (dry mouth), Red as a beet (cutaneous flushing), Hot as a hare (hyperthermia), Mad as a hatter (CNS effects)."]','A','Atropine blocks ALL muscarinic: dry, blind, fast, red, hot, mad. ANTICHOLINERGIC toxidrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Autonomic Nervous System','hard','flashcard','What is the pharmacological basis for using bethanechol in urinary retention?','["Bethanechol: direct-acting muscarinic agonist (M3-selective) that stimulates the detrusor muscle of the bladder (via M3 receptors → contraction) and relaxes the internal urethral sphincter, facilitating urination. Not broken down by AChE. Used in neurogenic urinary retention (e.g., post-operative, diabetic neurogenic bladder, drugs causing urinary retention). Contraindicated in: asthma (bronchoconstriction), GI obstruction, peptic ulcer."]','A','Bethanechol = muscarinic agonist = squeezes the bladder. The PEES drug.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Autonomic Nervous System','hard','flashcard','How does phenylephrine differ from epinephrine in its adrenergic receptor activity and clinical use?','["Phenylephrine: selective alpha1-adrenergic agonist. Effects: vasoconstriction → increased SVR → increased BP → REFLEX bradycardia (baroreceptor). No beta1 effects (no tachycardia). Used: nasal decongestant, hypotension (anaesthesia), topical mydriatic (eye drops). Epinephrine (adrenaline): non-selective alpha1+alpha2+beta1+beta2 agonist. Effects: increased HR and contractility (beta1), bronchodilation (beta2), vasoconstriction at high doses (alpha1). Used: anaphylaxis, cardiac arrest, severe asthma."]','A','Phenylephrine = pure alpha1 vasoconstrictor. Epinephrine = all receptors (alpha+beta).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Autonomic Nervous System','easy','flashcard','What are the locations of sympathetic ganglia compared to parasympathetic ganglia?','["Sympathetic ganglia: PARAVERTEBRAL (sympathetic chain ganglia, T1-L2) or PREVERTEBRAL (e.g., coeliac, superior mesenteric ganglia). Ganglia are CLOSE TO THE SPINAL CORD and FAR FROM the target organ. Therefore, sympathetic: short preganglionic, long postganglionic. Parasympathetic ganglia: NEAR OR IN THE TARGET ORGAN (e.g., ciliary, pterygopalatine, submandibular, otic ganglia). Long preganglionic, short postganglionic."]','A','Sympathetic ganglia near cord = long post-ganglionic. Parasympathetic near target = short post.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sleep Physiology','easy','flashcard','What are the stages of sleep and how does a typical night progress?','["NREM: N1 (lightest, theta waves, hypnagogic hallucinations), N2 (sleep spindles, K-complexes, 45-55% of total sleep), N3/SWS (slow-wave/delta sleep, deepest, hardest to wake). REM: vivid dreaming, EEG similar to wake, muscle atonia, REMs. Cycle: N1→N2→N3→N2→REM, every 90 min, 4-6 cycles/night. Early night: more SWS. Late night: more REM (longer REM periods)."]','A','N1 N2 N3 back to N2 then REM. 90 min cycles. Deep sleep early, REM late.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sleep Physiology','easy','flashcard','What is narcolepsy and what is its pathophysiology?','["Narcolepsy: chronic sleep disorder characterised by excessive daytime sleepiness (EDS) and intrusion of REM sleep features into wakefulness. Pathophysiology: autoimmune destruction of hypocretin (orexin)-producing neurons in the lateral hypothalamus (associated with HLA-DQB1*06:02). Clinical tetrad: EDS, Cataplexy (sudden muscle weakness triggered by emotion), Sleep paralysis, Hypnagogic/hypnopompic hallucinations. CSF orexin levels extremely low."]','A','Narcolepsy = orexin gone. Tetrad: EDS, Cataplexy, Sleep paralysis, Hallucinations. ECSH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sleep Physiology','medium','flashcard','What are sleep spindles and K-complexes and in which sleep stage do they occur?','["Sleep spindles: brief (0.5-2 s), 12-14 Hz EEG oscillations generated by thalamocortical circuits (thalamic reticular nucleus → relay nuclei → cortex loop). Represent active cortical inhibition, protecting sleep. K-complexes: large biphasic slow waves in response to stimuli, also in N2. Both characteristic of N2 NREM sleep. Sleep spindle density decreases in Alzheimer disease and schizophrenia."]','A','Spindles and K-complexes = N2 hallmarks. Spindles protect sleep. K-complex = the brain''''s WHAT WAS THAT?','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sleep Physiology','medium','flashcard','What neurotransmitters promote sleep vs. wakefulness?','["WAKEFULNESS: norepinephrine (locus coeruleus), serotonin (raphe nuclei), histamine (tuberomammillary nucleus), acetylcholine (basal forebrain, pedunculopontine nucleus), orexin/hypocretin (lateral hypothalamus). SLEEP: GABA and galanin (VLPO — inhibits all wake-promoting neurons), adenosine (homeostatic sleep pressure builds during wakefulness, blocked by caffeine), serotonin (initiates sleep but decreases during sleep)."]','A','Wake = NE, 5HT, Histamine, ACh, Orexin. Sleep = GABA (VLPO) + adenosine. Caffeine blocks adenosine!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sleep Physiology','medium','flashcard','What is the suprachiasmatic nucleus (SCN) and how does it regulate circadian rhythms?','["The SCN (in the anterior hypothalamus, above the optic chiasm) is the master circadian clock. It receives light input via the retinohypothalamic tract (melanopsin+ ipRGCs). The SCN drives circadian rhythms via: (1) neurohumoral signals (melatonin via pineal gland), (2) neural signals to the PVN and other hypothalamic nuclei, coordinating body temperature, cortisol, sleep-wake cycles. Period ~24.2 hours; light resets it daily."]','A','SCN sits above the OPTIC chiasm, gets light input, drives the 24h clock.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sleep Physiology','medium','flashcard','What is REM sleep behaviour disorder (RBD) and why is it clinically important?','["RBD: failure of normal REM-related muscle atonia, causing patients to physically ACT OUT their dreams (kicking, punching, shouting). Caused by degeneration of the brainstem nuclei that generate REM atonia (subcoeruleus nucleus and ventromedial medulla). Clinically important: RBD is a PRODROMAL MARKER of Parkinson disease and other alpha-synucleinopathies (MSA, DLB) — often precedes diagnosis by 10+ years. Diagnosis: polysomnography showing REM without atonia."]','A','RBD = acting out dreams. MAJOR clue for future Parkinson disease. Get PSG.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sleep Physiology','medium','flashcard','How does adenosine regulate sleep homeostasis?','["Adenosine: a homeostatic sleep pressure molecule. Accumulates in the brain during wakefulness (especially in the basal forebrain) as a byproduct of neuronal ATP consumption. Inhibits wake-promoting neurons (via A1 receptors) and activates VLPO (via A2A receptors). The longer you are awake, the more adenosine accumulates — increasing sleep drive. Caffeine works by COMPETITIVELY BLOCKING adenosine receptors (A1 and A2A), reducing sleep drive."]','A','Adenosine = the sleepy molecule. Caffeine blocks it = awake! Sleep to clear adenosine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sleep Physiology','hard','flashcard','What is the two-process model of sleep regulation (Borbely)?','["Process S (homeostatic): sleep pressure builds during wakefulness (due to adenosine accumulation, SHY hypothesis of synapse homeostasis) and dissipates during sleep. Reflected by slow-wave activity (SWA) in the EEG — increases with sleep deprivation. Process C (circadian): 24-hour oscillation driven by the SCN, promoting wakefulness during the day and sleep at night (via melatonin/core body temperature). Both processes interact: sleep occurs when circadian alerting signal wanes AND Process S is high."]','A','Process S = need to sleep. Process C = when to sleep. Two clocks work together.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sleep Physiology','hard','flashcard','What is the synaptic homeostasis hypothesis (SHY) and how does it relate to sleep function?','["SHY (Tononi and Cirelli): during wakefulness, learning and experience lead to net STRENGTHENING of synaptic connections throughout the brain (LTP). This consumes energy, takes up space, and adds noise. Sleep (especially SWS) restores synaptic homeostasis by DOWNSCALING synaptic strength globally (LTD-like processes), removing noise, and consolidating the most important memories. Evidence: SWA during sleep correlates with prior synaptic upscaling; post-sleep improvement in learning tasks."]','A','Awake = synapses grow (LTP). Sleep = synapses pruned/scaled down (LTD). Sleep = brain''''s defrag.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Sleep Physiology','easy','flashcard','What is sleep paralysis and why does it occur?','["Sleep paralysis: temporary inability to move or speak when falling asleep (hypnagogic) or waking up (hypnopompic). Lasts seconds to minutes. Caused by persistence of REM muscle atonia into the waking state (or premature intrusion into sleep onset). Often accompanied by vivid, frightening hallucinations. Common in narcolepsy but can occur in the general population (especially with sleep deprivation or irregular sleep schedules)."]','A','Sleep paralysis = REM atonia invades wakefulness. Terrifying but HARMLESS. Common with sleep deprivation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebral Circulation & CSF','easy','flashcard','What is the Monro-Kellie doctrine and its clinical significance?','["The Monro-Kellie doctrine: the skull is a rigid box containing three components: brain parenchyma (~80%), blood (~10%), and CSF (~10%). Because the skull is fixed, the sum of all three volumes is constant. Any increase in one component must be compensated by a decrease in another, otherwise ICP rises. Clinical significance: explains brain herniation, hydrocephalus, and the urgent need to address expanding haematomas/oedema."]','A','Fixed box = rigid skull. Brain + Blood + CSF = constant. Any expansion = ICP rises.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebral Circulation & CSF','easy','flashcard','What is the blood-brain barrier (BBB) and what can cross it?','["BBB: formed by tight junctions between brain endothelial cells, with supporting astrocyte endfeet and pericytes. Selectively permeable. CAN cross: lipid-soluble molecules (O2, CO2, ethanol, most general anaesthetics, steroids), specific carrier-mediated molecules (glucose via GLUT1, amino acids via LAT1), small molecules <500 Da. CANNOT cross: most drugs (problem in CNS drug delivery), large polar molecules, plasma proteins, bacteria. Exceptions: circumventricular organs (area postrema — responds to toxins in blood to trigger vomiting)."]','A','BBB: lipid = yes, carrier = yes, protein = NO. Tight junctions block the gap. Most drugs excluded.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebral Circulation & CSF','medium','flashcard','Describe the CSF circulation pathway from production to absorption.','["Production: choroid plexus (lateral ventricles > 4th > 3rd ventricle). Flow: lateral ventricles → foramen of Monro → 3rd ventricle → cerebral aqueduct of Sylvius → 4th ventricle → foramina of Luschka (lateral) and Magendie (medial) → subarachnoid space. Absorption: arachnoid granulations/villi into the dural venous sinuses (superior sagittal sinus). Also: glymphatic system via perivascular spaces (Virchow-Robin spaces) during sleep."]','A','Choroid → Monro → 3rd → Aqueduct → 4th → Luschka/Magendie → Sub-arachnoid → Arachnoid villi.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebral Circulation & CSF','medium','flashcard','What is normal CSF composition and how does it change in bacterial meningitis?','["Normal CSF: clear, colourless, pressure 70-200 mmH2O, protein 15-45 mg/dL, glucose 2/3 of serum glucose, WBC 0-5 cells/mm3 (lymphocytes), no RBCs, no bacteria. Bacterial meningitis: cloudy/turbid, HIGH pressure, HIGH protein (>100 mg/dL), LOW glucose (<2.2 mmol/L or <40% serum), HIGH WBC (predominantly NEUTROPHILS, >1000 cells/mm3), positive Gram stain/culture."]','A','Bacterial = cloudy, high pressure, high protein, LOW glucose, NEUTROPHILS. Viral = lymphocytes, normal glucose.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebral Circulation & CSF','medium','flashcard','What are the watershed zones of the brain and why are they important?','["Watershed (border) zones: areas of brain at the periphery of two arterial territories, maximally susceptible to ischaemia during systemic hypoperfusion (e.g., cardiac arrest, severe shock). Main watershed zones: (1) ACA/MCA junction: parasagittal cortex → proximal arm weakness (man in a barrel syndrome). (2) MCA/PCA junction: parietooccipital junction → cortical visual and somatosensory deficits. (3) Subcortical (internal watershed): periventricular white matter → lacunar infarcts pattern."]','A','Watershed = where two rivers barely meet = last to get water in drought. Cardiac arrest → watershed infarcts.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebral Circulation & CSF','medium','flashcard','What is cerebral perfusion pressure (CPP) and how is it calculated?','["CPP = MAP (mean arterial pressure) - ICP (intracranial pressure). Normal ICP: 7-15 mmHg. Normal MAP: ~90-100 mmHg. Normal CPP: ~70-80 mmHg. If CPP falls below 50 mmHg, cerebral blood flow becomes inadequate → ischaemia. If ICP approaches MAP, CPP → 0 → brain death. Clinical importance: in TBI/stroke management, target MAP is adjusted to keep CPP >60 mmHg."]','A','CPP = MAP - ICP. Minimum ~50 mmHg needed. Raised ICP crushes perfusion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebral Circulation & CSF','medium','flashcard','What are the cerebral sinuses and their clinical significance?','["Dural venous sinuses: superior sagittal sinus (receives cortical veins, CSF from arachnoid granulations), inferior sagittal sinus, straight sinus, transverse sinus, sigmoid sinus → internal jugular vein. Cavernous sinus: receives superior/inferior ophthalmic veins and sphenoparietal sinus; contains CN III, IV, V1, V2, VI and internal carotid artery. Clinical: cavernous sinus thrombosis (facial infection spreading via valveless emissary veins → proptosis, chemosis, multiple CN palsies, sepsis). Sagittal sinus thrombosis → raised ICP, venous infarcts."]','A','Cavernous sinus: CN 3 4 V1 V2 6 + ICA. Thrombosis = proptosis + multiple CN palsies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebral Circulation & CSF','hard','flashcard','What is the glymphatic system and how does it relate to sleep?','["The glymphatic system (Nedergaard et al.): a brain-wide waste clearance system using perivascular Virchow-Robin spaces (astrocyte aquaporin-4 (AQP4) water channels). CSF enters the brain along arterial perivascular spaces, exchanges with interstitial fluid, and exits along venous perivascular spaces into deep cervical lymphatics. Clearance is MOST ACTIVE DURING SLOW-WAVE SLEEP (10-fold more efficient than wakefulness) due to expansion of interstitial space. Function: clears amyloid-beta, tau, and other metabolic waste. Sleep deprivation reduces amyloid clearance — may contribute to Alzheimer disease risk."]','A','Glymphatic = brain''''s sewage system. Runs best during sleep. Sleep clears amyloid!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebral Circulation & CSF','hard','flashcard','What are the types of brain herniation and their clinical consequences?','["1) Transtentorial (uncal) herniation: medial temporal lobe (uncus) herniates through the tentorium → compresses ipsilateral CN III (dilated pupil) → compresses ipsilateral PCA (occipital infarction) → compresses midbrain (Duret haemorrhages = fatal). 2) Subfalcine (cingulate) herniation: cingulate gyrus under falx cerebri → may compress ACA → contralateral leg weakness. 3) Tonsillar herniation: cerebellar tonsils through foramen magnum → medulla compression → cardiorespiratory arrest. 4) Upward (transtentorial upward) herniation: posterior fossa mass pushes cerebellum upward."]','A','Transtentorial = CN III + PCA compression. Tonsillar = through foramen magnum = death. URGENT!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Anatomy & Physiology','Cerebral Circulation & CSF','easy','flashcard','What is papilloedema and what causes it?','["Papilloedema: bilateral optic disc swelling caused by raised intracranial pressure (ICP). Raised ICP is transmitted along the subarachnoid space surrounding the optic nerve, increasing pressure on the central retinal vein and impeding axoplasmic transport. Fundoscopy: blurred disc margins, obliteration of the cup, venous engorgement, haemorrhages. Important: papilloedema does NOT cause immediate visual loss (unlike anterior ischaemic optic neuropathy), but chronic papilloedema → optic atrophy → blindness."]','A','Papilloedema = raised ICP transmitted to optic sheath. Blurred discs on fundoscopy. Bilateral!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed');